Lemma pc1_walk : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo : Z) (G : word),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) -> WAI.senv m lo -> (lo + 544 <= bv_unsigned sp)%Z -> (0x6b3d78 <= lo)%Z ->
  ro_cells rsegs m 0x157b38 [C8 (Z_to_bv 64 0x6b3b40)] -> ro_cells rsegs m 0x6b3b40 [C8 G] ->
  a0 = Z_to_bv 64 0 -> a1 = Z_to_bv 64 0x23c40 ->
  evt rsegs (fun ms' => exists t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
      ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 0) a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F
               (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned sp - 544, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F
